    inputs: [{ role: "user", content: "What tools do you have access to?" }],
    tools: [
      {
        type: "connector",
        connectorId: "my_deepwiki",
        toolConfiguration: {
          include: ["ask_question"],
        },
      },
    ],
  });
}

main();
